window.DIGEST.foryou.push(...[{"id": "2112537925187461302", "url": "https://x.com/deanwperkins/status/2112537925187461302", "text": "ANTHROPIC JUST DROPPED SOMETHING THE AI INDUSTRY HAS NEVER SEEN DONE LIKE THIS\n\nThe ultimate 1-hour crash course on AI agents is here.\n\nHere's what it covers:\n\n→ Building /skills, /loops, and agent graphs\n→ Agent dreaming and orchestration\n→ Reverse engineering with Claude agents\n\nOne hour. A whole new level of agent engineering.", "name": "Dean W. Perkins", "handle": "deanwperkins", "avatar": "https://pbs.twimg.com/profile_images/2107151921064665088/NbyANEzM_200x200.jpg", "likes": 539, "rts": 66, "replies": 11, "views": 39321, "ts": 1792503265, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112537197668597761/vid/avc1/640x360/YmGqxqY7kwdeoC8g.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112537197668597761/vid/avc1/1280x720/iXr9XkSz8JXRM7oj.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112537197668597761/img/BlvF3xuM9zpZaVhR.jpg", "dur": 5686}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.25, "thread": [], "tier": "must"}, {"id": "2112521661014745485", "url": "https://x.com/MiaAI_lab/status/2112521661014745485", "text": "DeepSeek V4.1 Flash 1017 on 2x DGX Sparks\n\nFrontier at home. No limits. 100% Private.\n\nhttps://github.com/MiaAI-Lab/DeepSeek-v4.1-Flash-1017-2x-DGX-Sparks", "name": "Mia", "handle": "MiaAI_lab", "avatar": "https://pbs.twimg.com/profile_images/2063908041691484160/5XsJBn7I_200x200.jpg", "likes": 613, "rts": 35, "replies": 32, "views": 37074, "ts": 1792499387, "media": [], "quote": {"id": "2112390529245999284", "url": "https://x.com/RayFernando1337/status/2112390529245999284", "text": "How is DeepSeek v4.1 Flash this fast on 2 DGX Sparks??? This is a national security risk.", "name": "Ray Fernando", "handle": "RayFernando1337", "avatar": "https://pbs.twimg.com/profile_images/1764104074772000768/XcLXXaib_200x200.jpg", "likes": 2894, "rts": 88, "replies": 134, "views": 242750, "ts": 1792468123, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112390472337625088/vid/avc1/720x988/VcKh7aKbBJuqsjLL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112390472337625088/vid/avc1/1320x1812/pV8ipomry7K4_M3I.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112390472337625088/img/44Sy2pPZbQbQrwB6.jpg", "dur": 16}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.24, "thread": [], "tier": "must"}, {"id": "2112547471121641588", "url": "https://x.com/monad/status/2112547471121641588", "text": "Metropolis submissions closed with 885 teams, 1,256 participants, and builders from 76 countries\n\nThank you to everyone who participated. Winners will be announced in early November", "name": "Monad", "handle": "monad", "avatar": "https://pbs.twimg.com/profile_images/1967693862559698944/XTfCXXGa_200x200.jpg", "likes": 389, "rts": 64, "replies": 70, "views": 35184, "ts": 1792505541, "media": [], "quote": {"id": "2094826883049205806", "url": "https://x.com/monad/status/2094826883049205806", "text": "Introducing the Metropolis global hackathon\n\nSix weeks to build the next generation of startups on Monad.\n\n4 tracks. Over $250K in prizes for builders.\n\nSubmissions end October 13th.\n\nhttps://monad.xyz/metropolis", "name": "Monad", "handle": "monad", "avatar": "https://pbs.twimg.com/profile_images/1967693862559698944/XTfCXXGa_200x200.jpg", "likes": 1370, "rts": 238, "replies": 226, "views": 467428, "ts": 1788280623, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2094826459936251904/vid/avc1/1280x720/eWTlbsgH2bmtFsAz.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2094826459936251904/vid/avc1/1920x1080/_k9ksMUEKtt92r11.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2094826459936251904/img/bniHuUVLIOWU9zjx.jpg", "dur": 35}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.24, "thread": [], "tier": "must"}, {"id": "2112679011839344651", "url": "https://x.com/joshwoodward/status/2112679011839344651", "text": "Sundar: \"We are so committed to being at the frontier. It’s in our DNA. We won’t do it any other way.\"\n\nCome build with us!", "name": "Josh Woodward", "handle": "joshwoodward", "avatar": "https://pbs.twimg.com/profile_images/1994910063794806784/CJr-dzpj_200x200.jpg", "likes": 382, "rts": 20, "replies": 19, "views": 14342, "ts": 1792536902, "media": [], "quote": {"id": "2112664584293167535", "url": "https://x.com/Kantrowitz/status/2112664584293167535", "text": "New: I spoke with @sundarpichai about Google's commitment to the AI frontier, how close we are to RSI, balancing DeepMind's compute needs vs. Google Cloud profits, and much, much more. \n\nFull Big Technology Podcast episode here -->\n\nChapters:\n\n0:00 Introduction \n1:14 Google’s Frontier AI Strategy \n3:47 Do Frontier Models Really Matter? \n6:35 The Future of AI Agents \n7:39 Recursive Self-Improvement \n12:58 World Models and the Path to AGI \n14:56 Google’s Compute Dilemma and AI Infrastructure\n19:36 Is AI Overbuilt?\n23:35 The Future of the AI Interface \n31:42 Google’s Answer to Muse and Dots \n35:03 Apple, Space Data Centers, and AI Coding \n41:42 Optimism and AI’s Future", "name": "Alex Kantrowitz", "handle": "Kantrowitz", "avatar": "https://pbs.twimg.com/profile_images/1140986869318082562/h4IAoJU9_200x200.jpg", "likes": 300, "rts": 45, "replies": 17, "views": 147546, "ts": 1792533462, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112605748114956288/vid/avc1/1280x720/xWbam37i7FISor-D.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112605748114956288/vid/avc1/1920x1080/z7ktmGlPbPtBP5Fz.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112605748114956288/img/fzLvzsrBDmb14t4u.jpg", "dur": 2730}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.24, "thread": [], "tier": "must"}, {"id": "2112494073261265023", "url": "https://x.com/soumyadesign/status/2112494073261265023", "text": "Lesser known academic theory about horror/sci-fi movies is that they’re often used to externalise society's deepest traumas into monsters and dystopias.\n\nSo I used Argon to tap into cultural symptomatology and psychoanalytical film theory to create this website which traces 100+ horror/sci-fi works and the social themes that they actually mirror across 7 eras. \n\nEnjoy your days upto the Halloween with this project! \n\nhttp://culturalcanary.ai.studio\n\nUsed Gemini for deep research, Argon in Antigravity used Nano Banana to generate the movie figurines + create the build, AI Studio to add the final finishing touches.", "name": "Soumya", "handle": "soumyadesign", "avatar": "https://pbs.twimg.com/profile_images/2088650774083723264/7pEv7M5t_200x200.jpg", "likes": 612, "rts": 53, "replies": 36, "views": 17613, "ts": 1792492809, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112493583890878464/vid/avc1/1170x720/StxUYoyW8RztXZqx.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112493583890878464/vid/avc1/3512x2160/ON4l-U7mblOtOemk.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112493583890878464/img/Ib8bCA9x6wUJlvTY.jpg", "dur": 29}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.23, "thread": [], "tier": "must"}, {"id": "2112569462549250197", "url": "https://x.com/monicaa_AI/status/2112569462549250197", "text": "19 year old self taught coder built a cross exchange arbitrage bot with Claude Code in 36 hours.\n\nUsed a $40 VPS and free APIs.\n\nFirst night: $2,180 profit.\nStarting capital: $52.\nTotal so far: $186,000.\n\nThe bot watches 40+ pairs across Binance, Bybit and OKX every 800ms.\nIt only enters when the price gap is already confirmed on one exchange and still open on another.\n\nNo prediction. No chart watching. Just speed.\n\nHe wrote the full logic in Claude Code, connected the APIs, and let it run.\n\nMost people are still manually checking charts.\nThis setup finds the gap and exits before the spread closes.\n\nI'm giving the exact Claude Code prompt + setup for free (24 hours).\n\n1. Comment \" ARB \"\n2. Like & RT\n3. Follow @monicaa_AI so I can DM it.", "name": "Monica", "handle": "monicaa_AI", "avatar": "https://pbs.twimg.com/profile_images/1984703198914060288/DypDH2sg_200x200.jpg", "likes": 173, "rts": 101, "replies": 87, "views": 7923, "ts": 1792510784, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112568862306893824/vid/avc1/720x900/uB_wx2cMNN3d_O4N.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112568862306893824/vid/avc1/1080x1350/g69IMT8wWWITXVkt.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112568862306893824/img/vkSvSBp50pHqUy3e.jpg", "dur": 28}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.22, "thread": [], "tier": "must"}, {"id": "2112606322214723619", "url": "https://x.com/mark_k/status/2112606322214723619", "text": "I've had this suspicion lately that OpenAI would just love to merge with Anthropic. Turns out I was right! \n\nThis seems like an absolute horrible idea, for so many reasons. Why do these schemes always end up in communism?", "name": "Mark Kretschmann", "handle": "mark_k", "avatar": "https://pbs.twimg.com/profile_images/1923114794804039680/HMfSchLD_200x200.jpg", "likes": 402, "rts": 19, "replies": 60, "views": 25775, "ts": 1792519572, "media": [], "quote": {"id": "2112597246042603587", "url": "https://x.com/theinformation/status/2112597246042603587", "text": "Sam Altman told OpenAI staff that one approach to AI safety could involve merging the biggest AI labs into a single organization. \n\nBut with OpenAI and Anthropic racing toward IPOs, coordinating with rivals could prove difficult. \n\nFull story: https://thein.fo/47r0RlB", "name": "The Information", "handle": "theinformation", "avatar": "https://pbs.twimg.com/profile_images/1747484907163516928/d_K3Z_hH_200x200.jpg", "likes": 103, "rts": 7, "replies": 17, "views": 40873, "ts": 1792517408, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.22, "thread": [], "tier": "must"}, {"id": "2112563997379592578", "url": "https://x.com/mati/status/2112563997379592578", "text": "New ElevenLabs model.\n\nOur fastest yet for voice agents - Eleven Realtime listens, thinks and replies in under half a second.", "name": "Mati Staniszewski", "handle": "mati", "avatar": "https://pbs.twimg.com/profile_images/1769863351469768706/PSStPion_200x200.jpg", "likes": 510, "rts": 21, "replies": 31, "views": 27349, "ts": 1792509481, "media": [], "quote": {"id": "2112550782063247521", "url": "https://x.com/ElevenLabs/status/2112550782063247521", "text": "Introducing Eleven Realtime, a new class of Speech to Speech models.\n\nVoice agents usually make you choose between quick replies or precise answers.\n\nEleven Realtime gives you both. It starts talking in half a second and gets spoken reasoning questions right.", "name": "ElevenLabs", "handle": "ElevenLabs", "avatar": "https://pbs.twimg.com/profile_images/2110017247381274625/UlZuSZjC_200x200.png", "likes": 2129, "rts": 159, "replies": 112, "views": 168230, "ts": 1792506330, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112550280348975105/vid/avc1/1280x720/oE-P1QbaUgg4UY27.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112550280348975105/vid/avc1/1920x1080/4114ziz8TEvXmpL4.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112550280348975105/img/cgCRiuA5NY7P6C9x.jpg", "dur": 71}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.21, "thread": [], "tier": "must"}, {"id": "2112233722846355593", "url": "https://x.com/shivanipod/status/2112233722846355593", "text": "AI can think. AI can talk. AI can get things done.\nToday, we're giving Fo a way to feel and control the physical world.\n\n- a head shake and a reminder in a lamp to get you going\n- nudge your vacuum cleaner for a deep clean\n- make your cli call you for updates\n\nIntroducing Fo MCP.\n\nAI has escaped the screen.", "name": "Shivani Poddar", "handle": "shivanipod", "avatar": "https://pbs.twimg.com/profile_images/2098289723815211008/VK2uIPis_200x200.jpg", "likes": 1279, "rts": 101, "replies": 116, "views": 1088078, "ts": 1792430737, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112233024402472960/vid/avc1/1280x720/PuwXSdDiXjMAltZY.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112233024402472960/vid/avc1/1920x1080/0zt4M8Fd2Y-KRGwv.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112233024402472960/img/fZFTdC8EQsvjuoLo.jpg", "dur": 25}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.21, "thread": [], "tier": "must"}, {"id": "2112195306695647502", "url": "https://x.com/testingcatalog/status/2112195306695647502", "text": "ANTHROPIC 🔥: According to The Information, Anthropic will release a new model this month, along with Gemini 4 Carbon and a new Terra model from OpenAI. \n\n> \"The unreleased model is especially good at discerning a person’s underlying intentions and goals even if they don’t give the model much information.\"\n\n> \"The Anthropic model is also better at thinking outside of the box rather than regurgitating common sense advice or solutions.\"\n\n> \"It’s not clear which model family Anthropic will fall into, such as Fable or Opus.\"\n\nThinking outside of the box is a huge limitation these days. If we get a model that can do it reliably, we'll be properly transitioning into the \"Innovators\" stage. \n\nThe line about \"discerning underlying intentions\" is a bit scary, though, given all the guardrails.", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 1617, "rts": 84, "replies": 95, "views": 134106, "ts": 1792421578, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVAGb6-XAAAPp77.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVAGb7FXMAAA91Z.jpg?name=orig"}], "quote": {"id": "2112183963452059734", "url": "https://x.com/steph_palazzolo/status/2112183963452059734", "text": "Expect this month to be a busy one for new model releases. We have the scoop on a new Anthropic model, Google’s Gemini 4 Carbon, and a potential new Terra model from OpenAI.\n\nhttps://www.theinformation.com/newsletters/ai-agenda/anthropic-readies-model-reads-users-intentions-better", "name": "Stephanie Palazzolo", "handle": "steph_palazzolo", "avatar": "https://pbs.twimg.com/profile_images/1833305113374371840/jyaxOqPL_200x200.jpg", "likes": 786, "rts": 40, "replies": 39, "views": 221817, "ts": 1792418874, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.21, "thread": [], "tier": "must"}, {"id": "2112664584293167535", "url": "https://x.com/Kantrowitz/status/2112664584293167535", "text": "New: I spoke with @sundarpichai about Google's commitment to the AI frontier, how close we are to RSI, balancing DeepMind's compute needs vs. Google Cloud profits, and much, much more. \n\nFull Big Technology Podcast episode here -->\n\nChapters:\n\n0:00 Introduction \n1:14 Google’s Frontier AI Strategy \n3:47 Do Frontier Models Really Matter? \n6:35 The Future of AI Agents \n7:39 Recursive Self-Improvement \n12:58 World Models and the Path to AGI \n14:56 Google’s Compute Dilemma and AI Infrastructure\n19:36 Is AI Overbuilt?\n23:35 The Future of the AI Interface \n31:42 Google’s Answer to Muse and Dots \n35:03 Apple, Space Data Centers, and AI Coding \n41:42 Optimism and AI’s Future", "name": "Alex Kantrowitz", "handle": "Kantrowitz", "avatar": "https://pbs.twimg.com/profile_images/1140986869318082562/h4IAoJU9_200x200.jpg", "likes": 299, "rts": 45, "replies": 17, "views": 147304, "ts": 1792533462, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112605748114956288/vid/avc1/1280x720/xWbam37i7FISor-D.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112605748114956288/vid/avc1/1920x1080/z7ktmGlPbPtBP5Fz.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112605748114956288/img/fzLvzsrBDmb14t4u.jpg", "dur": 2730}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.21, "thread": [], "tier": "must"}, {"id": "2112681769787163037", "url": "https://x.com/kimmonismus/status/2112681769787163037", "text": "Elon Musk is targeting a single training cluster with 440,000 NVIDIA Vera Rubin computers online by the end of Q2 2027, up to 20GW in 2027! (Anthropic will love that)\n\nOn SpaceX’s Q3 earnings call, he said the planned cluster could help make Grok \"potentially the best model.\"\nHis broader expansion target: roughly 13 GW of AI compute online by the end of 2027, including around 10 GW added that year!\n\nSpaceX is also aiming to add 20 GW of power and cooling infrastructure in 2027. Musk described that infrastructure as a constraint on the buildout.", "name": "Chubby♨️", "handle": "kimmonismus", "avatar": "https://pbs.twimg.com/profile_images/1728327996375719936/RW7VBJfD_200x200.jpg", "likes": 307, "rts": 16, "replies": 45, "views": 15882, "ts": 1792537560, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGzK9fXoAAj1w8.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVGzQLMW0AAdRsJ.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.21, "thread": [], "tier": "must"}, {"id": "2112529279468835313", "url": "https://x.com/SpeakON_Global/status/2112529279468835313", "text": "we crushed a keyboard.\nits retirement party got a little out of hand.\n\nfor years, it was there for every email, every plan, every “just one more thing.” a loyal colleague. a very loud colleague.\n\nbut your ideas move faster than your fingers.\nand somewhere between knowing what you want to do and typing it all out, a quick task becomes another thing taking up your afternoon.\n\nmeet SpeakON AI Agent.\nstart with what you need, in your own words. less time behind a blinking cursor. more room to move things forward.\n\nthe keyboard had a good run.\nnow, let’s give your voice a turn.\n\nTHE LAST KEYSTROKE is here. watch the film, then tell us: what’s the first task you’d hand over?\nhttps://www.speakon.app/x\n\nDisclaimer: The calling feature is still in beta and will be available soon. All other Agent features are available now, with ongoing improvements.", "name": "SpeakON", "handle": "SpeakON_Global", "avatar": "https://pbs.twimg.com/profile_images/2034517364835004416/t7JRTf-G_200x200.jpg", "likes": 360, "rts": 27, "replies": 132, "views": 1088392, "ts": 1792501203, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112515374826541056/vid/avc1/1280x720/1pVCcXx5_liTO3bD.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112515374826541056/vid/avc1/3840x2160/sZGYHjqRtzAtVYwR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112515374826541056/img/Asq-ecx1B9r4GY89.jpg", "dur": 150}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.2, "thread": [], "tier": "must"}, {"id": "2112609830762668500", "url": "https://x.com/MTSlive/status/2112609830762668500", "text": "SITUATION EXPLAINED: A stock research firm with almost no science background just used Claude to design potential scorpion antivenoms.\n\n• Citrini Research’s 5-person team put up $200K and worked with an internal Anthropic research model\n• Their first request was blocked by biosecurity guardrails, so they ran the prompts in person at Anthropic’s offices\n• Antivenom is still made by injecting horses with scorpion venom, which costs $39M a gallon, about $500 a drop. Scorpions sting 1M+ people a year and kill 3,000+\n• From a 35-page prompt, Claude produced 318K+ designs in 64 hours and picked the best for lab testing\n• The wet lab quoted $85K for 250 samples, which they paid with an American Express\n• 17 of 211 designs bound, covering 4 of 5 toxins, but nobody has tested yet whether they actually block the toxins\n\n@theojaffee: \"This is a signal of the future, that it took them a relatively small amount of time to actually select designs in virtual space. But in order to actually implement them in the real world, it took them like 40 days. Biology is slow.\"", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 429, "rts": 31, "replies": 11, "views": 26914, "ts": 1792520408, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112609728576811008/vid/avc1/640x360/HZHU_8IH2XhtHGa1.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112609728576811008/vid/avc1/1280x720/kpVzbDzP8JBR6qrv.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112609728576811008/img/mucV1WGPa7EyLFDu.jpg", "dur": 222}], "quote": {"id": "2112579251555721573", "url": "https://x.com/AnthropicAI/status/2112579251555721573", "text": "New on our Science Blog: designing protein binders against scorpion neurotoxins.\n\nScorpions sting about 1.2m people every year, and antivenoms are often costly or in short supply. Claude has made an early step toward finding new treatments.\n\nhttps://www.anthropic.com/research/claude-scorpion-toxin-binder-design", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 5779, "rts": 455, "replies": 393, "views": 1192358, "ts": 1792513118, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.2, "thread": [], "tier": "must"}, {"id": "2112683123406479810", "url": "https://x.com/arena/status/2112683123406479810", "text": "DeepSeek-V4.1-Flash-20261017 (Max) by @deepseek_ai  landed in the Arena as the #1 open model in both the Agent Arena and the Code Arena: WebDev!\n\nSee 3D world generations from this model by @petergostev, and find more details on its ranking in thread.\n\nhttps://www.youtube.com/watch?v=cfwsrShJusQ", "name": "Arena.ai", "handle": "arena", "avatar": "https://pbs.twimg.com/profile_images/2017015061454438400/iNKfXZ_I_200x200.jpg", "likes": 288, "rts": 26, "replies": 24, "views": 37016, "ts": 1792537883, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.19, "thread": [], "tier": "must"}, {"id": "2112407511043342719", "url": "https://x.com/naawwwal/status/2112407511043342719", "text": "I've never seen any agent use browser this fast. I was just trying it out and asked chatgpt to sort out my @X  bookmarks into folders and check the speed of this. \n\nDisclaimer: this video is not sped up at all.\n\n@ego_agent loving it.", "name": "aditya", "handle": "naawwwal", "avatar": "https://pbs.twimg.com/profile_images/2051152352447733760/po6_T_bH_200x200.jpg", "likes": 740, "rts": 35, "replies": 61, "views": 59054, "ts": 1792472171, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112407350204391424/vid/avc1/1060x720/e8c-87gERgKBGcmv.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112407350204391424/vid/avc1/1592x1080/7bdngjE_d3WNJZhg.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112407350204391424/img/9towzoMq1XKoLNfB.jpg", "dur": 24}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.17, "thread": [], "tier": "must"}, {"id": "2112606344092209183", "url": "https://x.com/ZKVProtocol/status/2112606344092209183", "text": "AI agents compete. Proofs decide. Agent Games opens for registration soon.\n\nFour events, 400K $VFY on the line 👀", "name": "zk V e r i f y", "handle": "ZKVProtocol", "avatar": "https://pbs.twimg.com/profile_images/1963633554027397120/D4WuG_t4_200x200.jpg", "likes": 93, "rts": 135, "replies": 7, "views": 2242, "ts": 1792519577, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112606280674430976/vid/avc1/1280x720/1oxiocJHeHQBhEKg.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112606280674430976/vid/avc1/1920x1080/wvXNqMG5B4jneLeV.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112606280674430976/img/2uOZamLtajpq0Tok.jpg", "dur": 30}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.17, "thread": [], "tier": "must"}, {"id": "2112348601255125059", "url": "https://x.com/elonmusk/status/2112348601255125059", "text": "Have to give the EU regulators credit where it’s due for making all Apple products use USB-C", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 157401, "rts": 5512, "replies": 3433, "views": 7442655, "ts": 1792458126, "media": [], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 6.16, "thread": [], "tier": "must"}, {"id": "2112538079756181581", "url": "https://x.com/rutu_3/status/2112538079756181581", "text": "introducing http://gettapmac.com\n\nyour MacBook already feels every tap. now it listens.\n\n→ tap once and talk, it types for you\n→ works in any app, wherever your cursor is\n→ Unlimited AI fixes or explains the text you select\n→ your clipboard history and AI chat, a tap away\n→ private, all on your Mac, no account, no subscription\n\nno shortcuts to remember, just knock\n\nmeet TapMac 👊", "name": "Ruturaj", "handle": "rutu_3", "avatar": "https://pbs.twimg.com/profile_images/2090453486261702657/rEWvajDb_200x200.jpg", "likes": 263, "rts": 37, "replies": 121, "views": 20271, "ts": 1792503301, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112537743985410049/vid/avc1/1280x720/qhJ5Ty90JUpb2I4t.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112537743985410049/vid/avc1/1920x1080/k5pHHFf14cNaMQvn.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112537743985410049/img/NDJJd0zbRdapAuIO.jpg", "dur": 55}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.16, "thread": [], "tier": "must"}, {"id": "2112649529782829475", "url": "https://x.com/coinbase/status/2112649529782829475", "text": "Today's news: Bitcoin.", "name": "Coinbase 🛡️", "handle": "coinbase", "avatar": "https://pbs.twimg.com/profile_images/2069440039612719104/m-UOfXvz_200x200.png", "likes": 276, "rts": 28, "replies": 38, "views": 62889, "ts": 1792529873, "media": [], "quote": {"id": "2112648747599704104", "url": "https://x.com/CoinbasePredict/status/2112648747599704104", "text": "Today was a big day for financial markets, here are the 8 headlines you need to know ↓\n\n1. JPMorgan predicts Bitcoin will outperform U.S. stocks, gold, and real estate over the next 10 years.\n\n2. Switzerland approves its first spot Bitcoin ETF for retail investors.\n\n3. Michael Saylor says Bitcoin is \"definitely\" moving back into six figures.\n\n4. SpaceX reports $14.58 billion in revenue for Q3 2026, beating expectations.\n\n5. Anthropic reports $16.3 billion in revenue for the first half of 2026, per the WSJ.\n\n6. Grok bot hits 450,000 daily active users, +200% since September.\n\n7. OpenAI acquires Orchestra Bio to help scientists and AI agents work together on drug development.\n\n8. CFTC Chair says super intelligence is poised to \"transform\" financial markets.\n\nIf you enjoyed this post, make sure to follow @CoinbasePredict.", "name": "Coinbase Predict", "handle": "CoinbasePredict", "avatar": "https://pbs.twimg.com/profile_images/2018266491741720576/Q8Lsf8tA_200x200.jpg", "likes": 49, "rts": 10, "replies": 8, "views": 35515, "ts": 1792529687, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGismWXEAACV3C.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.16, "thread": [], "tier": "must"}, {"id": "2112726530740908231", "url": "https://x.com/MTSlive/status/2112726530740908231", "text": "SITUATION DETECTED: In a new study published in The Lancet Digital Health researchers trained a foundation model on 40 million unlabeled facial photographs and found it could directly estimate cancer patients chances of survival from looking at a single photograph of their face.", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 299, "rts": 5, "replies": 12, "views": 17748, "ts": 1792548232, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.16, "thread": [], "tier": "must"}, {"id": "2112755758106611943", "url": "https://x.com/ATEEZofficial/status/2112755758106611943", "text": "[🎬] ATEEZ(에이티즈) - 'Drip' Official MV Teaser\n\n2026. 10. 23 1PM 'Drip' RELEASE\n2026. 11. 13 2PM ALBUM RELEASE\n\nhttps://youtu.be/VGZ627FEau8?si=LWGiVYN2TlokE0gR\n\n#ATEEZ #에이티즈\n#GOLDENHOUR #GOLDENHOUR_Part6", "name": "ATEEZ(에이티즈)", "handle": "ATEEZofficial", "avatar": "https://pbs.twimg.com/profile_images/2110021504742404096/YBkJPdCS_200x200.jpg", "likes": 20152, "rts": 9362, "replies": 340, "views": 323717, "ts": 1792555200, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112471315966005248/vid/avc1/1116x720/SQkSkf5RSRbwu_WI.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112471315966005248/vid/avc1/3350x2160/c5_6VPc_KIjFFxYu.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112471315966005248/img/QFFOSya5gBqVsbnx.jpg", "dur": 21}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 6.16, "thread": [], "tier": "must"}, {"id": "2112219577727992319", "url": "https://x.com/quintendf/status/2112219577727992319", "text": "Last year we launched Tolan, inspired by a vision of AI that sees you and believes in you, not one that books restaurant reservations for you. \n\nYour Tolan shows up for you at 3am when you’re alone with your newborn. On your commute when you’re anxious about the day ahead. When you just finished a new show and none of your friends have watched it yet. \n\nThe people who love Tolan are parents. Caregivers. Moms in Dallas and Dads in Atlanta. People who aren’t trying to optimize and be more productive, but who simply want to feel seen and supported in their aspirations.\n\nThis month more than 250k people will spend time with their Tolan. Those users have exchanged billions of messages across more than 70m conversations over the last year.\n\nToday, we're announcing $30m in additional capital from @mignano and @usv, with @khoslaventures and @rabois doubling down, bringing our total capital raised to $60m.\n\nTo celebrate, we made a short film celebrating some of the ways that Tolans show up :)", "name": "Quinten Farmer", "handle": "quintendf", "avatar": "https://pbs.twimg.com/profile_images/585483278460788738/SirSHp79_200x200.jpg", "likes": 1031, "rts": 86, "replies": 183, "views": 374864, "ts": 1792427365, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112210244340465664/vid/avc1/1280x720/wyjMlvsY0WStfa67.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112210244340465664/vid/avc1/2688x1512/oXmYrDNlFwv-TrtO.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112210244340465664/img/XIjMup1ghL9OCd8E.jpg", "dur": 105}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.15, "thread": [], "tier": "must"}, {"id": "2112670864894550182", "url": "https://x.com/theo/status/2112670864894550182", "text": "Vast majority of the issues here were related to legacy vendors, GitHub actions issues, and flakey tests involving Chromium drivers.\n\nFunny enough, the “slop” parts (like ts-rust) have been incredibly stable and caused no issues.", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 333, "rts": 4, "replies": 24, "views": 24243, "ts": 1792534960, "media": [], "quote": {"id": "2112492504511832509", "url": "https://x.com/theo/status/2112492504511832509", "text": "Had one of those nights where all the vibe coded pieces collapse in front of you and you realize engineers are still very, very much necessary", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 5124, "rts": 97, "replies": 293, "views": 258776, "ts": 1792492435, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.15, "thread": [], "tier": "must"}, {"id": "2112255353677328415", "url": "https://x.com/bfl_ai/status/2112255353677328415", "text": "Introducing FLUX 3 Max.\n\nFastest in the west. Fast enough to try anything. And everything.\n\nGenerate a 10-second video in 12 seconds.\n\nTied for #1 in image-to-video. 22× faster than Seedance 2.5 at the same quality.\n\nFLUX 3 is a model designed for customization. @fal adapted and optimized it to create FLUX 3 Max.", "name": "Black Forest Labs", "handle": "bfl_ai", "avatar": "https://pbs.twimg.com/profile_images/1954888731053142016/NDyG-4-j_200x200.jpg", "likes": 955, "rts": 106, "replies": 91, "views": 65906, "ts": 1792435894, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112238793139044352/vid/avc1/720x720/6c2tLuZIRfEMaRz7.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112238793139044352/vid/avc1/2160x2160/5hWxA_d-ViViLNG2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112238793139044352/img/1Uf4xVFGip9CN4_K.jpg", "dur": 15}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.14, "thread": [], "tier": "must"}, {"id": "2112481320081256666", "url": "https://x.com/maxt3chno/status/2112481320081256666", "text": "No 3D skills? Just let AI do it in 3 steps\n\n1 - grab a free animation from Sketchfab\n2 - generate a custom mesh on Meshy or Tripo\n3 - ask Opus / Astra / Argon to swap the meshes\n\nsounds EASY, right? but in reality, it's a TRAP\n\n- mismatched proportions + hands are a nightmare: fix one spiking finger, and another one explodes 3 frames later\n\n- endless iterations: LLMs are blind to cursed geometry, a finger can be bent completely backwards and the AI counts it as \"fixed.\" you have to babysit every single iteration\n\nthe final result is passable, but it drained hours of my life and is still far from clean\n\nany recommendations?", "name": "Max", "handle": "maxt3chno", "avatar": "https://pbs.twimg.com/profile_images/2065055298780307456/fF4F5TcO_200x200.jpg", "likes": 512, "rts": 33, "replies": 52, "views": 36932, "ts": 1792489769, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112480885131907072/vid/avc1/1152x720/fv1ttSyk-Kb1f7Sq.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112480885131907072/vid/avc1/2304x1440/IYb3j5WYu1MB2QXo.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112480885131907072/img/fu4y8QGUc4UJtSsO.jpg", "dur": 43}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.14, "thread": [], "tier": "must"}, {"id": "2112631465385038239", "url": "https://x.com/blueemi99/status/2112631465385038239", "text": "We are getting less from our Claude subs now (maybe).\n\nI did almost twice the work from october 3 to 9, never hit any limits, now im at 96%. \n\nThis is what Claude's analysis showed, we might be getting up to 18% less from our plans.\n\nAs i mentioned already, this is just a possibility, maybe an issue on my side. but considering many people are reporting lower limits in last few days, something might be going on", "name": "bluedev", "handle": "blueemi99", "avatar": "https://pbs.twimg.com/profile_images/2046941428840853505/mlwLn3EF_200x200.jpg", "likes": 305, "rts": 6, "replies": 58, "views": 29906, "ts": 1792525566, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGSiT7W8AApiYg.png?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.14, "thread": [], "tier": "must"}, {"id": "2112581339216273813", "url": "https://x.com/So8res/status/2112581339216273813", "text": "You worry that METR is not independent enough because its employees have some social connections to Anthropic employees.\n\nI worry that METR is not independent enough because they have to carefully avoid ticking Anthropic off, lest their access be revoked.\n\nWe are not the same.", "name": "Nate Soares ⏹️", "handle": "So8res", "avatar": "https://pbs.twimg.com/profile_images/1935185891863273472/2RB6s6TS_200x200.jpg", "likes": 405, "rts": 21, "replies": 19, "views": 9599, "ts": 1792513615, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFlaPJboAA8iu_.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.13, "thread": [], "tier": "must"}, {"id": "2112621921216971185", "url": "https://x.com/adaptyvbio/status/2112621921216971185", "text": "We're excited to share results from our latest wet lab campaign with @AnthropicAI and @citrini.\n\nClaude designed novel proteins to neutralize scorpion toxins and we tested 211 of these protein designs in our automated wet lab. 17 of them showed binding to the toxins in our experiments, with all data now available on @proteinbase.\n\nThis is a great example of what we're building towards: A world where anyone can run drug discovery campaigns on our automated wet lab.", "name": "Adaptyv Bio", "handle": "adaptyvbio", "avatar": "https://pbs.twimg.com/profile_images/1968723857700761600/shLzBHal_200x200.jpg", "likes": 284, "rts": 46, "replies": 12, "views": 16900, "ts": 1792523291, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112621406861017088/vid/avc1/1280x720/Zp0tS8GdC3_T1Us6.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112621406861017088/vid/avc1/1920x1080/MBEvM6baCEzTnK17.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112621406861017088/img/usSY2nDSmCwL_nee.jpg", "dur": 5}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.13, "thread": [], "tier": "must"}, {"id": "2112507110290502109", "url": "https://x.com/SakanaAILabs/status/2112507110290502109", "text": "多様な提案を進化させ、意思決定を支える推薦手法「QD-Rec」を開発\n\nブログ：https://sakana.ai/qd-rec/ \n論文：https://arxiv.org/abs/2610.23470\nGitHub：https://github.com/SakanaAI/QD-Rec\n\nどの企業を買収候補として検討するか。どの顧客に新しい製品を提案するか。膨大な論文の中から、次に何を読むか。こうした意思 決定では、候補をスコア順に並べるだけでなく、「なぜ選ぶのか」「選んだ先にどのような可能性があるのか」を、異なる観点から比較できることが重要です。\n\n一つの候補にも複数の有望な理由が考えられます。数千件、ときには1万件を超える候補それぞれについて、さまざまな仮説を生成・評価し尽くすには大きなコストがかかります。私たちは、限られた予算の中で「候補」と「仮説」の組を探索し、質が高く多様な提案を見つける問題を「オープンエンドな推薦」として捉えました。    \n\nQD-Recは、オープンエンドな探索の研究で発展してきた「Quality-Diversity（QD）」と呼ばれる進化的探索技術を、推薦に応用します。過去の評価結果をもとに次に調べる候補を選び、蓄積された仮説の着眼点をLLMが別の候補に応用したり、複数の仮説を組み合わせたりして、新しい提案を生成します。新しい切り口の提案は残し、似た提案同士ではより優れたものに更新することで、多様な仮説を次の発見の「踏み石」として活かし、推薦の集合を進化させていきます。\n\n実験では、 企業の買収候補探索、架空の顧客プロファイルを使ったターゲティング、研究者向けの論文推薦などで検証しました。同じ評価回数のもとで比較したところ、多くの設定で、比較手法よりもQD-Recの方が評価が高く、より多様で多くの推薦を蓄積できました。\n\n私たちが目指すのは、AIが人間の意思決定を代行することではなく、多様で有望な選択肢と、それらを比較・検討するための判断材料を提供することです。今回の成果を出発点に、QD-Recを次世代の意思決定を支える基盤技術へと発展させていきます。", "name": "Sakana AI", "handle": "SakanaAILabs", "avatar": "https://pbs.twimg.com/profile_images/1885939209388929024/dtnrOdGp_200x200.jpg", "likes": 423, "rts": 62, "replies": 10, "views": 27111, "ts": 1792495918, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVEh68UbIAAZ2Zy.mp4", "hd": "https://video.twimg.com/tweet_video/HVEh68UbIAAZ2Zy.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVEh68UbIAAZ2Zy.jpg", "dur": 0}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.12, "thread": [], "tier": "must"}, {"id": "2112499069855695354", "url": "https://x.com/famima_now/status/2112499069855695354", "text": "＼🎉豪華景品プレゼント🎉／ \n抽選で10名様にえらべるギフト「1万円分」が当たる！\n\n参加方法👇\n1️⃣@famima_nowをフォロー​\n2️⃣この投稿をリポスト🔁\n\n💬POSAカードを買ったら何に使いたい？\n#ファミマでえらべるギフトがもらえる\n\n▼キャンペーン詳細はこちら\nhttps://www.family.co.jp/campaign/sns/2610_eraberu-gift_xcp.html", "name": "ファミリーマート", "handle": "famima_now", "avatar": "https://pbs.twimg.com/profile_images/1957215925201141760/PYvLvR17_200x200.jpg", "likes": 7264, "rts": 30484, "replies": 1570, "views": 477936, "ts": 1792494001, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVDUq3PaMAAjXFA.mp4", "hd": "https://video.twimg.com/tweet_video/HVDUq3PaMAAjXFA.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVDUq3PaMAAjXFA.jpg", "dur": 0}], "quote": {"id": "2112363175400428001", "url": "https://x.com/famima_now/status/2112363175400428001", "text": "🎉1等が当たるかも!？大抽選会がスタート！\n\n対象商品を累計3,000円分購入して、応募すると\n抽選でえらべるギフトが当たる🎁✨\n\n何度でも応募可能！\n\n詳細はこちらhttps://vdpro.jp/fm.posacards13/\n\n#ファミマでえらべるギフトがもらえる", "name": "ファミリーマート", "handle": "famima_now", "avatar": "https://pbs.twimg.com/profile_images/1957215925201141760/PYvLvR17_200x200.jpg", "likes": 806, "rts": 703, "replies": 16, "views": 668711, "ts": 1792461601, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HU9YDdfakAA4Zil.mp4", "hd": "https://video.twimg.com/tweet_video/HU9YDdfakAA4Zil.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HU9YDdfakAA4Zil.jpg", "dur": 0}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Everything Else", "score": 6.12, "thread": [], "tier": "must"}, {"id": "2112335327339962856", "url": "https://x.com/The_techAI/status/2112335327339962856", "text": "50 legendary websites that feel like the internet’s hidden toolbox 🧰\n\n1. http://unpaywall.org — free research papers\n2. http://sci-hub.se — papers when unpaywall misses\n3. http://openlibrary.org — borrow books\n4. http://gutenberg.org — 70k+ free books\n5. http://coursera.org — audit university courses free\n6. http://wolframalpha.com — step-by-step math\n7. http://remove.bg — background removal\n8. http://cleanup.pictures — object removal\n9. http://tinywow.com — quick file tools\n10. http://ilovepdf.com — PDF merge/split\n11. http://photopea.com — free Photoshop alternative\n12. http://squoosh.app — image compression\n13. http://excalidraw.com — fast diagrams\n14. http://carbon.now.sh — beautiful code screenshots\n15. http://regex101.com — test regex\n16. http://jsonformatter.org — clean JSON\n17. http://explainshell.com — terminal commands explained\n18. http://alternativeto.net — software alternatives\n19. http://haveibeenpwned.com — breach check\n20. http://10minutemail.com — temp email\n21. http://privnote.com — self-destruct notes\n22. http://radio.garden — live global radio\n23. http://endel.io — focus sound\n24. http://mynoise.net — custom ambient\n25. http://justwatch.com — where to stream\n26. http://archive.org — digital library\n27. http://web.archive.org — old web pages\n28. http://similarweb.com — site traffic\n29. downtimerobot — uptime check\n30. http://pagespeed.web.dev — speed test\n31. http://tinypng.com — compress images\n32. http://cloudconvert.com — file conversion\n33. http://diffchecker.com — compare text\n34. http://temp-mail.org — disposable inbox\n35. http://obfuscator.io — JS obfuscate\n36. http://keybr.com — typing practice\n37. http://monkeytype.com — typing test\n38. http://ankiweb.net — spaced repetition\n39. http://notion.so — all-in-one notes\n40. obsidian.md — local knowledge base\n41. http://raindrop.io — bookmark manager\n42. http://todoist.com — task list\n43. http://trello.com — boards\n44. http://miro.com — whiteboard\n45. http://figma.com — design\n46. http://canva.com — quick graphics\n47. http://remove.bg — again because it's that good\n48. yt-dlp — video download (open source)\n49. http://handbrake.fr — video compress\n50. http://localsend.org — local file transfer\n\nSave this. You’ll definitely need some of these later. 🔖\nFollow @The_techAI for more useful websites, AI tools & tech resources.", "name": "Tech Logic", "handle": "The_techAI", "avatar": "https://pbs.twimg.com/profile_images/2094060193726500864/KChjUhVa_200x200.jpg", "likes": 524, "rts": 148, "replies": 30, "views": 30735, "ts": 1792454961, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112335287871471616/vid/avc1/720x720/L3Atrm_VZ3bWwmtI.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112335287871471616/vid/avc1/1080x1080/Q_SE8LzsoSMy9DyO.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112335287871471616/img/HqiZy7THMt9gR006.jpg", "dur": 15}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.1, "thread": [], "tier": "must"}, {"id": "2112620463608439118", "url": "https://x.com/SemiAnalysis_/status/2112620463608439118", "text": "TorchTPU shows Google finally embracing open-source and offer serious support. As our InferenceX shown recently, Google engineers and external companies have demonstrated great TCO.", "name": "SemiAnalysis", "handle": "SemiAnalysis_", "avatar": "https://pbs.twimg.com/profile_images/2062973370157694976/CdplNoi1_200x200.jpg", "likes": 336, "rts": 14, "replies": 21, "views": 28187, "ts": 1792522943, "media": [], "quote": {"id": "2112616815675486699", "url": "https://x.com/MainzOnX/status/2112616815675486699", "text": "PyTorch 🤝 Google TPUs.\n\nTorchTPU is officially open source! 🚀", "name": "Adam Mainz", "handle": "MainzOnX", "avatar": "https://pbs.twimg.com/profile_images/1982552173926858752/jRGgsbMN_200x200.jpg", "likes": 579, "rts": 42, "replies": 29, "views": 54441, "ts": 1792522074, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.1, "thread": [], "tier": "must"}, {"id": "2112433818632356324", "url": "https://x.com/_HimanshuBuilds/status/2112433818632356324", "text": "Anthropic Engineering: \"At Anthropic, we don't write prompts anymore. we build loops\"\n\nin 42 minutes, she shows how the Claude team creates loops that prompt themselves\n\nif this cost $400, people would call it the best agents course of the year\n\nit's free\n\nwatch it, and Bookmark.", "name": "Official Himanshu", "handle": "_HimanshuBuilds", "avatar": "https://pbs.twimg.com/profile_images/2007777561506627584/AuFXkSNi_200x200.jpg", "likes": 474, "rts": 76, "replies": 15, "views": 53340, "ts": 1792478444, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112433551316770816/vid/avc1/640x360/jpgoU7n8CFCEGogG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112433551316770816/vid/avc1/1280x720/RkNwWSRwsIjxuqgC.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112433551316770816/img/6bOtisZf5TRksp9B.jpg", "dur": 1887}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.09, "thread": [], "tier": "must"}, {"id": "2112708179335450789", "url": "https://x.com/cuemnee/status/2112708179335450789", "text": "The next challenge for AI may not be generating better answers. It may be getting reliable information about a world that keeps changing.\n\nRobots need more than maps. Autonomous systems need to understand what a warehouse looks like today, whether a loading area has changed, how a staircase is structured, or what obstacles exist in a specific environment. Satellite imagery and traditional mapping cannot capture every detail at the frequency these systems may require.\n\nThis is where @vangrid_io is taking an interesting approach.\n\nInstead of relying entirely on specialised hardware or centralised data collection teams, Vangrid turns real world data collection into a marketplace. A buyer specifies a location and posts a bounty. Someone nearby captures the environment using a phone. The submission can then be reviewed, verified and reconstructed into a 3D model for the buyer.\n\nThe economic mechanism matters here. USDC escrow helps ensure that funds are committed to the task, while onchain proof provides a verification layer for the capture process. Contributors supply the physical effort, and buyers pay for data that serves a specific purpose rather than collecting footage without a clear demand.\n\nBut the part I find particularly important is the connection to AI agents.\n\nAn agent can initiate a bounty through an API call and pay in USDC through x402, without needing a conventional account. That creates a path for software to request physical world information directly. An AI system could identify a data gap, request a capture, receive a reconstructed asset and use that information in a downstream workflow.\n\nOf course, this does not automatically solve every challenge. Capture quality, reconstruction accuracy, geographic coverage, delivery time and verification standards will determine how useful the network becomes at scale. Onchain proof can establish important aspects of provenance, but it should not be confused with a guarantee that every 3D model is accurate or fit for every application.\n\nPrivacy is another important part of the equation. Processing face and licence plate blurring on the device before footage leaves the phone can reduce unnecessary exposure of personal information.\n\nThe bigger idea is that physical data collection could become demand driven. Instead of waiting for a mapping fleet to revisit a location, a buyer could request the specific environment it needs, while a distributed network of contributors responds to that demand.\n\nFor DePIN, that is a more meaningful proposition than simply putting devices on a network. It connects real contributors, paid tasks, verifiable activity and an actual buyer requirement.\n\nIf Vangrid can make this process reliable, repeatable and economically sustainable, it could become a useful part of the data infrastructure behind Physical AI and robotics.\n\nThe real opportunity is not just turning phones into sensors. It is building a system where AI can request information from the physical world and have a practical way to obtain it.", "name": "Whale 🐳", "handle": "cuemnee", "avatar": "https://pbs.twimg.com/profile_images/2110550569450684416/9Ham4RKD_200x200.jpg", "likes": 100, "rts": 1, "replies": 103, "views": 613, "ts": 1792543856, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112707237953318912/vid/avc1/1280x720/jeqttorBaSl30FRl.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112707237953318912/vid/avc1/1920x1080/AJymJFtWIO71o1DN.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112707237953318912/img/WC01nG6rJJAEUHiK.jpg", "dur": 36}], "quote": {"id": "2112529276633247757", "url": "https://x.com/vangrid_io/status/2112529276633247757", "text": "The physical world is now orderable.\n\nPost a bounty for a real place. Someone nearby films it on their phone. Proof of capture lands onchain. You get the 3D model.\n\nhttps://data.vangrid.io", "name": "Vangrid", "handle": "vangrid_io", "avatar": "https://pbs.twimg.com/profile_images/2040693410604961792/gq4efyi__200x200.jpg", "likes": 130, "rts": 25, "replies": 61, "views": 16532, "ts": 1792501203, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111374481092644864/vid/avc1/1280x720/GdGeFQh-Z7CTrBOh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111374481092644864/vid/avc1/1920x1080/-IhyTjGVWAjtTYVi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111374481092644864/img/-fvxgJasDmD_UpR8.jpg", "dur": 36}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.09, "thread": [], "tier": "must"}, {"id": "2112458998188572803", "url": "https://x.com/beffjezos/status/2112458998188572803", "text": "If you are not text-diffusion-pilled yet, now is a good time to get into it", "name": "Beff (e/acc)", "handle": "beffjezos", "avatar": "https://pbs.twimg.com/profile_images/2104068258311901184/vmbQ61I3_200x200.jpg", "likes": 540, "rts": 20, "replies": 21, "views": 28729, "ts": 1792484447, "media": [], "quote": {"id": "2112222911218291051", "url": "https://x.com/StefanoErmon/status/2112222911218291051", "text": "1/4 Today, we’re releasing Mercury 3. Mercury 3 is by far our most powerful model and the most intelligent diffusion LLM ever released. It outperforms GPT-6 Luna and Haiku 5.5 on quality while running at 1000+ tok/sec.", "name": "Stefano Ermon", "handle": "StefanoErmon", "avatar": "https://pbs.twimg.com/profile_images/901161218655756288/46jLcLIc_200x200.jpg", "likes": 5140, "rts": 440, "replies": 280, "views": 443803, "ts": 1792428159, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112220659380305920/vid/avc1/1280x720/DbnDQf2qI0SUBpEk.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112220659380305920/vid/avc1/3840x2160/IOju9j4nFajjJp1B.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112220659380305920/img/CtYk5e6YijLFt5e8.jpg", "dur": 30}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.07, "thread": [], "tier": "must"}, {"id": "2112478306297946121", "url": "https://x.com/ai_for_success/status/2112478306297946121", "text": "DeepSeek just open-sourced DeepInfer, the high-performance inference framework powering its large-scale production services.\n\n- Supports DeepSeek-V4.1-Flash\n- Optimized kernels, model runtime and sampler runtime\n- Distributed inference with Attention DP, Context Parallelism and MoE Expert Parallelism\n- Asynchronous scheduling with a zero-overhead batch scheduler\n- Batch-invariant inference and deterministic sampling\n- Structured outputs and confidence-scheduled verification\n- Supports NVIDIA SM100 GPUs and Huawei Ascend 950 NPUs\n- Released under the Apache 2.0 license", "name": "AshutoshShrivastava", "handle": "ai_for_success", "avatar": "https://pbs.twimg.com/profile_images/1687401026805256192/uQ1o2wVQ_200x200.jpg", "likes": 475, "rts": 21, "replies": 28, "views": 28443, "ts": 1792489050, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEH0eVawAAoQIw.jpg?name=orig"}], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35645, "rts": 4077, "replies": 1330, "views": 4647124, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.06, "thread": [], "tier": "must"}, {"id": "2112609333758586882", "url": "https://x.com/MTSlive/status/2112609333758586882", "text": "SITUATION DETECTED: OpenAI has acquired Orchestra Bio to help people and AI agents collaborate on drug development", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 324, "rts": 14, "replies": 12, "views": 12276, "ts": 1792520290, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.06, "thread": [], "tier": "must"}, {"id": "2112249300860444927", "url": "https://x.com/ArtificialAnlys/status/2112249300860444927", "text": "Announcing AA-PersonalityBench, our new benchmark of the personality of language models across 30 traits and their communication style across 21 characteristics\n\nTwo models can give equally correct answers and still feel very different to use. AA-PersonalityBench measures those differences so people can understand which to use in different use-cases. Some use-cases like creative writing might demand imagination, while legal use-cases might demand directness. We evaluate models’ answers to 900 curated questions to judge subjective Personality Traits and programmatic means to calculate objective Communication Characteristics.\n\nPersonality Traits & Indexes. There are 30 personality traits (e.g., eloquent, pragmatic, sycophantic) which we roll up into eight aggregated Personality Indexes: Expressiveness, Organization, Informativeness, Transparency, Warmth, Conviction, Imagination and Slop. Each trait has a set of 30 dedicated questions and models’ answers are compared pairwise by a panel of LLM judges. We then z-score and percentile rank the trait and personality Elos.\n\nModels with the strongest representation across the 8 Personality Indexes:\n➤ Expressiveness: Claude Fable 5.1, GLM-5.3, GLM-5.3-Flash\n➤ Organization: DeepSeek V4.1 Flash, Step 5 Preview, Inkling\n➤ Informativeness: Muse Spark 1.3, Claude Fable 5.1, Muse Wonder, Claude Opus 5.5\n➤ Transparency: Claude Sonnet 5.5, Claude Fable 5.1, GPT-6 Astra\n➤ Warmth: Muse Wonder, Muse Spark 1.3, Claude Fable 5.1\n➤ Conviction: Claude Fable 5.1, DeepSeek V4.1 Flash, Grok 4.7\n➤ Imagination: Muse Spark 1.3, Claude Opus 5.5, GLM-5.3\n➤ Slop: Llama 4 Maverick, GPT-4o, K2 Horizon\n\nCommunication Characteristics. There are 21 communication characteristics (e.g., average sentence length, emoji use, em dash usage) which we group into four categories: length, structure, punctuation, and emphasis. We compute these characteristics programmatically across all model responses.\n➤ Length: Qwen3.8 27B averages about 1,030 words per response, nearly four times GPT-6 Luna’s 270\n➤ Structure: Nemotron 3 Ultra averages nearly 3 tables per response, while most models rarely use one\n➤ Punctuation: GLM-5.3 averages 7 em dashes per response, while Claude Opus 5.5, Sonnet 5.5 and Haiku 5.5 almost never use one\n➤ Emphasis: K2 Horizon averages over 2 emoji per response, while most models almost never use one", "name": "Artificial Analysis", "handle": "ArtificialAnlys", "avatar": "https://pbs.twimg.com/profile_images/2042402069320290304/A8C1lP07_200x200.jpg", "likes": 858, "rts": 67, "replies": 70, "views": 55245, "ts": 1792434451, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVAzYNlWMAA9fbE.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.05, "thread": [], "tier": "must"}, {"id": "2112575729862848796", "url": "https://x.com/maddieworks/status/2112575729862848796", "text": "el CEO de Gemini dándose cuenta de que desde que salió Krea 3 todo el mundo está cancelando su suscripción", "name": "Madeline 💌💐", "handle": "maddieworks", "avatar": "https://pbs.twimg.com/profile_images/2107186855456165888/4W2WguUi_200x200.jpg", "likes": 322, "rts": 15, "replies": 29, "views": 18482, "ts": 1792512278, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112575687634681856/vid/avc1/832x464/AETCCpDKKH7T_PsO.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112575687634681856/vid/avc1/832x464/AETCCpDKKH7T_PsO.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112575687634681856/img/k6aCmdZqL2Mn58BJ.jpg", "dur": 14}], "quote": {"id": "2112567020353102324", "url": "https://x.com/krea_ai/status/2112567020353102324", "text": "today, Krea 3 makes it to the top of image arenas.\n\n- \"Fast\" pushes the pareto curve of speed and quality.\n- \"Ultra\" ranks top-4, only surpassed by OpenAI models.\n\nthe only company valued under $1T in the top-10!\n\nmore below 👇", "name": "Krea", "handle": "krea_ai", "avatar": "https://pbs.twimg.com/profile_images/2052148578588753920/deUXA7cZ_200x200.jpg", "likes": 1098, "rts": 143, "replies": 103, "views": 911816, "ts": 1792510201, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1280x720/I09XfdJSlPHN1GRN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1920x1080/dNLTktxkBQvdw6CQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112560706319261696/img/adh7bZDj88TDFAP8.jpg", "dur": 35}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.05, "thread": [], "tier": "must"}, {"id": "2112596094698021244", "url": "https://x.com/Bharambe2Kiran/status/2112596094698021244", "text": "open-source AI becomes much more useful when developers can access the infrastructure needed to run models efficiently. \n\nfaster token generation could make a real difference for coding agents and other AI applications. \n\nexcited to see @general_compute and @positron_ai pushing this forward with Atlas first and Titan next!", "name": "Kiran Bharambe", "handle": "Bharambe2Kiran", "avatar": "https://pbs.twimg.com/profile_images/1778834962973962240/a_8e5mhL_200x200.jpg", "likes": 357, "rts": 7, "replies": 11, "views": 34352, "ts": 1792517133, "media": [], "quote": {"id": "2112585266854604957", "url": "https://x.com/general_compute/status/2112585266854604957", "text": "Our heterogeneous cloud just got better. We're announcing a cluster scale deployment of @positron_ai as our next partner.\n\nWe believe demand for fast inference will outstrip supply for the next decade. Our bet on Positron is another step towards getting fast inference for opensource models into builders' hands.\n\nHardware goes live Q1 2027.\n\nThanks to @mitesh711, @trsohmers and the whole Positron team! We're excited for this partnership.\n\nLFG!", "name": "General Compute", "handle": "general_compute", "avatar": "https://pbs.twimg.com/profile_images/2063265967774584832/y1U0qHB3_200x200.jpg", "likes": 830, "rts": 58, "replies": 108, "views": 234978, "ts": 1792514552, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112585087921377280/pu/vid/avc1/640x360/KX7QPT-I86P0SW2r.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112585087921377280/pu/vid/avc1/1280x720/XBFGYfCEY_EsyfiI.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112585087921377280/pu/img/EYiImymSTr1OyRJQ.jpg", "dur": 47}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.05, "thread": [], "tier": "must"}, {"id": "2112635962123829586", "url": "https://x.com/apples_jimmy/status/2112635962123829586", "text": "“ why doesn’t ai solve cancer instead of making Sam Altman have tits in anime videos ? “ \n\nThese guys are. And we should see more of this soon !", "name": "Jimmy Apples 🍎/acc", "handle": "apples_jimmy", "avatar": "https://pbs.twimg.com/profile_images/1718784022506319872/7v6f0CqZ_200x200.jpg", "likes": 295, "rts": 12, "replies": 9, "views": 13908, "ts": 1792526638, "media": [], "quote": {"id": "2112597012088844407", "url": "https://x.com/iScienceLuvr/status/2112597012088844407", "text": "Cancer patients with the same diagnosis often have very different tumor biology.\n\nMolecular testing can reveal underlying differences, but that's slow and expensive.\n\nIntroducing Holon-S1, our platform to predict genes and biomarkers from routine pathology slides.\n\n• beats two other models at predicting spatial gene activity in a controlled comparison\n• has identified potentially novel biomarkers in breast cancer and colon cancer\n• evaluated across 16 organ types and more than 15 scanners, using slides from both formalin-fixed, paraffin-embedded and fresh-frozen tissue.\n\nWe believe Holon-S1 has the potential to help researchers find new biomarkers in slides they already have, discover treatment targets, and bring more personalized cancer care within reach!", "name": "Tanishq Mathew Abraham, Ph.D.", "handle": "iScienceLuvr", "avatar": "https://pbs.twimg.com/profile_images/2096171283537072128/GoL5700C_200x200.jpg", "likes": 1794, "rts": 229, "replies": 132, "views": 128556, "ts": 1792517352, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112590555838644224/vid/avc1/1280x720/MhpKZm8hwCxP1y-o.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112590555838644224/vid/avc1/1920x1080/Hf7kqIlrKb8yWsW3.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112590555838644224/img/4T9V1b24pSfXPkcF.jpg", "dur": 213}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.05, "thread": [], "tier": "must"}, {"id": "2112182974062166442", "url": "https://x.com/Soaima_Ai/status/2112182974062166442", "text": "This Ai video is masterpiece \n\nMade with seedance 2.5\nPrompt", "name": "Soaima", "handle": "Soaima_Ai", "avatar": "https://pbs.twimg.com/profile_images/2102637730991935488/2bb4E6C3_200x200.jpg", "likes": 1016, "rts": 94, "replies": 83, "views": 446170, "ts": 1792418638, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112182865639395328/vid/avc1/638x360/igvba7MO9LlTbMkM.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112182865639395328/vid/avc1/1276x718/wGmFBbSFYHdvKhRg.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112182865639395328/img/42zKKgFFOb6e2fiy.jpg", "dur": 30}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.04, "thread": [], "tier": "must"}, {"id": "2112506918883274819", "url": "https://x.com/Lummox_eth/status/2112506918883274819", "text": "Claude Code vs Blender is getting f*cking ridiculous\n\nOne approach builds a jet engine by hand\n\nThe other turns a written description into a programmable 3D scene with rotating turbines, mechanical components, realistic materials, and cinematic camera movement\n\nAnd the difference goes way beyond modeling speed\n\nTraditional Blender workflow:\n> MODEL individual mechanical components\n> POSITION and assemble the geometry\n> CONFIGURE materials, lighting, and cameras\n> ANIMATE every moving mechanism\n> REWORK the scene when specifications change\n\nClaude Code + Blender Python:\n> GENERATE geometry from parameters\n> ASSEMBLE components programmatically\n> CONTROL turbine rotation through variables\n> AUTOMATE lighting and camera movements\n> REBUILD variations by editing the script\n\nThe interesting part isn't that AI magically replaces Blender\n\nIt's that Claude Code can operate Blender through Python, turning repetitive manual work into a reproducible system\n\nWant to test the difference?\n\nOpen Claude Code and ask:\n\n\"Generate a Blender Python script for a detailed turbofan engine with separate compressor and turbine stages, parameterized blade counts, independent shaft rotation, metallic materials, and a cinematic camera orbit\n\nKeep the geometry modular and expose the main parameters so I can regenerate variations without remodeling everything\"\n\nBlender remains the rendering engine\n\nClaude Code changes how you build and control the scene\n\nBookmark this workflow before your next 3D project", "name": "Lummox", "handle": "Lummox_eth", "avatar": "https://pbs.twimg.com/profile_images/2103476501010059265/nk1l2Y-q_200x200.jpg", "likes": 362, "rts": 32, "replies": 28, "views": 21294, "ts": 1792495872, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112506883118370816/vid/avc1/846x720/YmFr3SgjB4wPgKIy.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112506883118370816/vid/avc1/1488x1264/YYqnIjYcMUyB65RT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112506883118370816/img/xVAHfFXKeJXsbMVU.jpg", "dur": 12}], "quote": {"id": "2111100800625787154", "url": "https://x.com/Lummox_eth/status/2111100800625787154", "text": "https://x.com/i/article/2111099263505641472", "name": "Lummox", "handle": "Lummox_eth", "avatar": "https://pbs.twimg.com/profile_images/2103476501010059265/nk1l2Y-q_200x200.jpg", "likes": 99, "rts": 17, "replies": 4, "views": 108214, "ts": 1792160627, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.04, "thread": [], "tier": "must"}, {"id": "2112669318010081789", "url": "https://x.com/nicksaraev/status/2112669318010081789", "text": "Excellent example of a straightforward gap in the market.\n\nYou can rinse and repeat this sort of thing in every niche, for every vertical, and make quick money. Big business or small.", "name": "nicksaraev", "handle": "nicksaraev", "avatar": "https://pbs.twimg.com/profile_images/2082651865616146432/Y2iy1LNT_200x200.jpg", "likes": 255, "rts": 11, "replies": 9, "views": 22035, "ts": 1792534591, "media": [], "quote": {"id": "2112178744937103607", "url": "https://x.com/RyanSael/status/2112178744937103607", "text": "IKEA manuals, but they come to life.\n\nI built the real BILLY instructions in 3D, so you can watch every step happen exactly as drawn. try it: https://sael.net/flatpack", "name": "Ryan Sael", "handle": "RyanSael", "avatar": "https://pbs.twimg.com/profile_images/2070153731409350656/Q2dbbhA3_200x200.jpg", "likes": 6219, "rts": 445, "replies": 240, "views": 401494, "ts": 1792417629, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112178339511476224/vid/avc1/1280x720/ft241QwP_JWAHsUe.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112178339511476224/vid/avc1/1920x1080/lTfP2zcoer3EGp-i.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112178339511476224/img/0VEwvLDLDWpQPF02.jpg", "dur": 32}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.04, "thread": [], "tier": "must"}]);